BEGIN;

CREATE TABLE IF NOT EXISTS "students" ("student_id" TEXT PRIMARY KEY, "student_name" TEXT, "status" TEXT);

CREATE TABLE IF NOT EXISTS "programs" ("program_id" TEXT PRIMARY KEY, "program_name" TEXT, "duration_years" INTEGER, "tuition_fee" INTEGER);

CREATE TABLE IF NOT EXISTS "feeschedules" ("fee_schedule_id" TEXT PRIMARY KEY, "program_id" TEXT, "term_id" TEXT, "tuition_fee" INTEGER, "lab_fee" INTEGER, "exam_fee" INTEGER);

CREATE TABLE IF NOT EXISTS "enrollments" ("enrollment_id" TEXT PRIMARY KEY, "student_id" TEXT, "program_id" TEXT, "term_id" TEXT, "status" TEXT);

CREATE TABLE IF NOT EXISTS "invoices" ("invoice_id" TEXT PRIMARY KEY, "enrollment_id" TEXT, "student_id" TEXT, "fee_schedule_id" TEXT, "invoice_date" TEXT, "due_date" TEXT, "total_amount" INTEGER, "status" TEXT);

CREATE TABLE IF NOT EXISTS "invoice_lines" ("line_id" TEXT PRIMARY KEY, "invoice_id" TEXT, "fee_type" TEXT, "amount" INTEGER);

CREATE TABLE IF NOT EXISTS "eligibility" ("eligibility_id" TEXT PRIMARY KEY, "student_id" TEXT, "gpa" REAL, "family_income" INTEGER, "eligible" TEXT);

CREATE TABLE IF NOT EXISTS "scholarships" ("scholarship_id" TEXT PRIMARY KEY, "student_id" TEXT, "enrollment_id" TEXT, "invoice_id" TEXT, "award_amount" INTEGER, "status" TEXT);

CREATE TABLE IF NOT EXISTS "payments" ("payment_id" TEXT PRIMARY KEY, "student_id" TEXT, "payment_date" TEXT, "amount" INTEGER, "payment_method" TEXT);

CREATE TABLE IF NOT EXISTS "payment_allocations" ("allocation_id" TEXT PRIMARY KEY, "payment_id" TEXT, "invoice_id" TEXT, "allocated_amount" INTEGER);

CREATE TABLE IF NOT EXISTS "refunds" ("refund_id" TEXT PRIMARY KEY, "student_id" TEXT, "payment_id" TEXT, "refund_amount" INTEGER, "reason" TEXT);

CREATE TABLE IF NOT EXISTS "student_balances" ("student_id" TEXT PRIMARY KEY, "invoice_total" INTEGER, "scholarship_total" INTEGER, "payment_total" INTEGER, "allocated_payment_total" INTEGER, "refund_total" INTEGER, "final_balance" INTEGER);

CREATE TABLE IF NOT EXISTS "anomaly_cases" ("issue_id" TEXT PRIMARY KEY, "issue_type" TEXT, "entity_name" TEXT, "record_id" TEXT, "related_record_id" TEXT, "source_value" INTEGER, "anomalous_value" INTEGER, "expected_outcome" TEXT);

CREATE TABLE IF NOT EXISTS "ground_truth" ("issue_id" TEXT PRIMARY KEY, "issue_type" TEXT, "record_id" TEXT, "amount" INTEGER, "expected_outcome" TEXT);

COMMIT;
